52	export const dynamic = "force-dynamic";
53	
54	function fmtUptime(seconds: number): string {
55	  if (!seconds || seconds <= 0) return "—";
56	  const d = Math.floor(seconds / 86400);
57	  const h = Math.floor((seconds % 86400) / 3600);
58	  const m = Math.floor((seconds % 3600) / 60);
59	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
60	}
61	
62	type LiveStats = {
63	  cpu?: number;
64	  mem?: number;
65	  maxmem?: number;
66	  uptime?: number;
67	  netin?: number;
68	  netout?: number;
69	} | null;
70	
71	export default async function ServerPage({
72	  params,
73	  searchParams,
74	}: {
75	  params: Promise<{ id: string }>;
76	  searchParams: Promise<{ tab?: string }>;
77	}) {
78	  const [{ id }, { tab }] = await Promise.all([params, searchParams]);
79	  const user = await requireUser();
80	  const server = await db.server.findUnique({
81	    where: { id },
82	    include: {
83	      plan: true,
84	      osTemplate: true,
85	      project: true,
86	      portForwards: { orderBy: { publicPort: "asc" } },
87	      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
88	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
89	      dedicatedIp: true,
90	      // Needed to price a renewal correctly: a game server bills its game plan's
91	      // flat price, not the base VPS plan's term price.
92	      gamePlan: true,
93	    },
94	  });
95	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
96	
97	  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
98	  // display value through the decrypt fallback (legacy plaintext rows still work).
99	  const rootPassword = serverRootPassword(server);
100	
101	  const [projects, activePlans, osTemplates, extraDiskPriceCents, backupPlusCents, annualPct] = await Promise.all([
102	    db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
103	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
104	    db.osTemplate.findMany({
105	      where: { active: true, category: "PLAIN_OS" },
106	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
107	    }),
108	    extraDiskPerGbCents(),
109	    backupPlusMonthlyCents(),
110	    // Live annual discount — feeds the "Renew now" quote below AND the resize
111	    // pickers, so an annual server's renewal/upgrade/downgrade all price against the
112	    // same rate it was sold at.
113	    annualDiscountPct(),
114	  ]);
115	
116	  // VAT/GST for the SERVER OWNER (Finding 1), resolved from their billing country.
117	  const owner =
118	    server.userId === user.id ? user : (await db.user.findUnique({ where: { id: server.userId } })) ?? user;
119	  const renewTaxCtx = await taxContextForUser(owner);
120	
121	  // What "Renew now" will actually charge, priced through the SAME function the
122	  // action charges through, so the button cannot quote one figure and take
123	  // another. See lib/renewal-quote.ts for the incident.
124	  const renewQuote = renewalQuote(
125	    {
126	      termMonths: server.termMonths,
127	      extraDiskGB: server.extraDiskGB,
128	      plan: { name: server.plan.name, priceCents: server.plan.priceCents },
129	      // A game server is sold at its game plan's flat price, NOT the base VPS
130	      // plan it happens to be built on. Omitting this quoted an $8.99 renewal for
131	      // a $4.99 product.
132	      gamePlan: server.gamePlan
133	        ? { name: server.gamePlan.name, priceCents: server.gamePlan.priceCents, termMonths: server.gamePlan.termMonths }
134	        : null,
135	      dedicatedIp: server.dedicatedIp,
136	      backupTier: server.backupTier,
137	    },
138	    {
139	      ipMonthlyCents: server.dedicatedIp ? await dedicatedIpMonthlyCents() : 0,
140	      extraDiskPerGbCents: extraDiskPriceCents,
141	      backupPlusCents,
142	      annualDiscountPct: annualPct,
143	      // VAT/GST for the owner (Finding 1): the "Renews at $X" figure and the Renew
144	      // now quote are tax-inclusive, matching what renewNow charges.
145	      taxRatePercent: renewTaxCtx.ratePercent,
146	    },
147	  );
148	
149	  // The server's REAL disk: plan allowance + any separately-purchased extra disk.
150	  // Every disk figure on this page uses this, never `plan.diskGB` on its own.
151	  const totalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
152	
153	  const publicIp = process.env.PUBLIC_IP ?? "";
154	  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
155	  const busy =
156	    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
157	  const steady = ["RUNNING", "STOPPED"].includes(server.status);
158	
159	  let live: LiveStats = null;
160	  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
161	  let backups: { volid: string; ctime?: number; size?: number }[] = [];
162	  let pveUnavailable = false;
163	
164	  if (server.vmid && steady) {
165	    const results = await Promise.allSettled([
166	      vmStatus(server.vmid),
167	      listSnapshots(server.vmid),
168	      listBackups(server.vmid),
169	    ]);
170	    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
171	    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
172	    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
173	    pveUnavailable = results.some((r) => r.status === "rejected");
174	  }
175	
176	  const sshCommand = server.sshPort ? `ssh root@${publicIp} -p ${server.sshPort}` : null;
177	
178	  // Single-item terminal list for this server — connect string computed the
179	  // same way as the Claude Code hub (dedicated IP → own IP, else NAT SSH port).
180	  const terminalServers = [
181	    {
182	      id: server.id,
183	      hostname: server.hostname,
184	      connect: server.dedicatedIp
185	        ? `ssh root@${server.dedicatedIp.address}`
186	        : `ssh -p ${server.sshPort ?? 22} root@${publicIp || "YOUR_SERVER_IP"}`,
187	    },
188	  ];
189	
190	  // SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
191	  // port 22; NAT servers use the platform public IP + the forwarded SSH port.
192	  const dedicated = !!server.dedicatedIp;
193	  const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
194	  const sftpPort = dedicated ? 22 : server.sshPort;
195	  const isGameServer = GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
196	
197	  // Per-game customization (only for game servers with a customization schema).
198	  const gameFamily = familyFor(server);
199	  const gameSchema = schemaFor(gameFamily);
200	  const gameVariant =
201	    gameSchema && server.gameVariant && isValidVariant(gameFamily!, server.gameVariant)
202	      ? server.gameVariant
203	      : gameSchema?.defaultVariant ?? "";
204	  const gameValidated = gameFamily
205	    ? validateConfig(gameFamily, (server.gameConfig as Record<string, unknown> | null) ?? {})
206	    : null;
207	  const gameValues = gameValidated && gameValidated.ok ? gameValidated.values : {};
208	
209	  /* ---------- Tab: Overview ---------- */
210	  const overview = (
211	    // `grid-cols-1` is load-bearing below `md`. With no base template the browser
212	    // creates an IMPLICIT `auto` track, sized to min-content and unclampable: at
213	    // 390px the rehearsal measured it at 530px — the `ssh root@… -p …` <code> and
214	    // the SFTP/SSH credentials are unbreakable strings — scrolling the whole page
215	    // 156px sideways. `grid-cols-1` compiles to `repeat(1, minmax(0, 1fr))`, the
216	    // same minmax `md:grid-cols-2` already applies, which is why desktop was fine.
217	    <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
218	      <div className="card">
219	        <h2 className="mb-4 font-semibold">Access</h2>
220	        <dl className="space-y-3 text-sm">
221	          <div>
222	            <dt className="text-slate-400">SSH command</dt>
223	            <dd className="mt-1 flex items-center gap-2">
224	              {/* min-w-0 + overflow-x-auto so a long/IPv6 SSH command scrolls
225	                  inside its own box instead of widening the card at 390px —
226	                  parity with the hardened SftpAccess command strings. */}
227	              <code className="min-w-0 flex-1 overflow-x-auto whitespace-nowrap rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
228	                {sshCommand ?? "provisioning…"}
229	              </code>
230	              {sshCommand && <CopyText text={sshCommand} />}
231	            </dd>
232	          </div>
233	          <div className="flex items-center justify-between">
234	            <dt className="text-slate-400">Root password</dt>
235	            <dd>
236	              {rootPassword ? (
237	                <RevealPassword password={rootPassword} />
238	              ) : (
239	                <span className="text-slate-500">—</span>
240	              )}
241	            </dd>
242	          </div>
243	          <div className="flex items-center justify-between">
244	            <dt className="text-slate-400">Private IP</dt>
245	            <dd className="font-mono text-xs">{server.ipAddress ?? "—"}</dd>
246	          </div>
247	        </dl>
248	        <div className="divider" />
249	        <div className="flex flex-wrap items-center justify-between gap-2">
250	          <p className="text-xs text-slate-500">
251	            Lost access or rotating credentials? Generate a fresh root password.
252	          </p>
253	          <ResetPasswordButton serverId={server.id} disabled={busy || !steady} />
254	        </div>
255	      </div>
256	
257	      <SftpAccess
258	        host={sftpHost}
259	        port={sftpPort}
260	        password={rootPassword}
261	        dedicated={dedicated}
262	      />
263	
264	      {isGameServer && (
265	        <div className="md:col-span-2">
266	          <GameAutoUpdate
267	            serverId={server.id}
268	            gameName={server.osTemplate.name}
269	            autoUpdate={server.autoUpdate}
270	            canUpdate={server.status === "RUNNING"}
271	            busy={busy}
272	          />
273	        </div>
274	      )}
275	
276	      {server.gamePlanId && gameSchema && (
277	        <div className="md:col-span-2">
278	          <GameSettings
279	            serverId={server.id}
280	            schema={gameSchema}
281	            variant={gameVariant}
282	            values={gameValues}
283	            disabled={busy || !steady}
284	          />
285	        </div>
286	      )}
287	
288	      <div className="card">
289	        <h2 className="mb-4 font-semibold">Live stats</h2>
290	        {live ? (
291	          <div className="space-y-4 text-sm">
292	            <div>
293	              <div className="mb-1.5 flex justify-between">
294	                <span className="text-slate-400">CPU</span>
295	                <span className="font-semibold">{((live.cpu ?? 0) * 100).toFixed(1)}%</span>
296	              </div>
297	              <MeterBar value={(live.cpu ?? 0) * 100} max={100} />
298	            </div>
299	            <div>
300	              <div className="mb-1.5 flex justify-between">
301	                <span className="text-slate-400">Memory</span>
302	                <span className="font-semibold">
303	                  {fmtBytes(live.mem ?? 0)} / {fmtBytes(live.maxmem ?? 0)}
304	                </span>
305	              </div>
306	              <MeterBar value={live.mem ?? 0} max={live.maxmem ?? 1} color="#3b82f6" />
307	            </div>
308	            <div className="flex justify-between">
309	              <span className="text-slate-400">Uptime</span>
310	              <span className="font-semibold">{fmtUptime(live.uptime ?? 0)}</span>
311	            </div>
312	            <div className="flex justify-between">
313	              <span className="text-slate-400">Network I/O</span>
314	              <span className="font-mono text-xs">
315	                {fmtBytes(live.netin ?? 0)} in · {fmtBytes(live.netout ?? 0)} out
316	              </span>
317	            </div>
318	          </div>
319	        ) : (
320	          <p className="text-sm text-slate-400">
321	            {pveUnavailable
322	              ? "Hypervisor is briefly unavailable — stats will reappear shortly."
323	              : "Live stats appear once the server is provisioned."}
324	          </p>
325	        )}
326	      </div>
327	
328	      <div className="card">
329	        <h2 className="mb-4 font-semibold">Configuration</h2>
330	        <dl className="space-y-2.5 text-sm">
331	          <div className="flex justify-between">
332	            <dt className="text-slate-400">Plan</dt>
333	            <dd>
334	              {server.plan.name} — {server.plan.cpuCores} vCPU / {server.plan.ramMB / 1024} GB /{" "}
335	              {totalDiskGB} GB NVMe
336	              {server.extraDiskGB > 0 && (
337	                <span className="block text-xs text-slate-500">
338	                  {server.plan.diskGB} GB plan + {server.extraDiskGB} GB added storage
339	                </span>
340	              )}
341	            </dd>
342	          </div>
343	          <div className="flex justify-between">
344	            <dt className="text-slate-400">Bandwidth</dt>
345	            <dd>{server.plan.bandwidthTB} TB / month</dd>
346	          </div>
347	          <div className="flex justify-between">
348	            <dt className="text-slate-400">Operating system</dt>
349	            <dd>{server.osTemplate.name}</dd>
350	          </div>
351	          <div className="flex justify-between">
352	            <dt className="text-slate-400">Created</dt>
353	            <dd>{server.createdAt.toISOString().slice(0, 10)}</dd>
354	          </div>
355	          <div className="flex justify-between">
356	            <dt className="text-slate-400">{server.isFree ? "Billing" : "Renews"}</dt>
357	            <dd>
358	              {server.isFree
359	                ? "Free — never expires"
360	                : server.expiresAt
361	                  ? server.expiresAt.toISOString().slice(0, 10)
362	                  : "—"}
363	            </dd>
364	          </div>
365	        </dl>
366	      </div>
367	
368	      {!server.isFree ? (
369	        // The "Price /mo" the card shows must agree with what Renew now charges.
370	        // A game server is sold at its game plan's flat price, so its monthly
371	        // run-rate is that price over its term — NOT the base VPS plan.priceCents
372	        // it is built on, which would read $8.99/mo beside a $4.99 renewal on the
373	        // same card. Both figures derive from renewQuote, the single shared
374	        // formula, and extra disk mirrors renewalCharge (game plans carry no
375	        // add-on line, so showing one would overstate the monthly).
376	        <RenewalCard
377	          serverId={server.id}
378	          autoRenew={server.autoRenew}
379	          expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
380	          priceCents={
381	            server.gamePlan
382	              ? Math.round(renewQuote.totalCents / renewQuote.months)
383	              : server.plan.priceCents
384	          }
385	          extraDiskGB={server.extraDiskGB}
386	          extraDiskMonthlyCents={server.gamePlan ? 0 : extraDiskCentsAt(server.extraDiskGB, extraDiskPriceCents)}
387	          suspendedUnpaid={server.status === "SUSPENDED" && !!server.suspendedNote?.includes("unpaid")}
388	          renewTotalCents={renewQuote.totalCents}
389	          renewDurationLabel={renewQuote.durationLabel}
390	        />
391	      ) : (
392	        <div className="card">
393	          <h2 className="mb-3 font-semibold">Subscription</h2>
394	          <p className="text-sm text-slate-400">
395	            This server is free of charge — no billing, no expiry.
396	          </p>
397	        </div>
398	      )}
399	
400	      {!server.isFree && server.status !== "DELETING" && (
401	        <div className="card md:col-span-2">
402	          <CancelService
403	            serverId={server.id}
404	            hostname={server.hostname}
405	            expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
406	            autoRenew={server.autoRenew}
407	            refundEstimateCents={terminationRefundCents({
408	              isFree: server.isFree,
409	              expiresAt: server.expiresAt,
410	              isGame: !!server.gamePlanId,
