"use client";

import { useCallback, useEffect, useMemo, useState, useTransition } from "react";
import {
  getServerMods,
  installMod,
  uninstallMod,
  type ModsView,
  type CatalogMod,
} from "@/lib/actions-mods";

/**
 * Mods tab — browse the per-game mod/plugin catalog and one-click install /
 * uninstall onto this server. Data + mutations come from lib/actions-mods.ts;
 * the panel polls while a change is applying so status updates live.
 */
export function GameMods({ serverId }: { serverId: string }) {
  const [view, setView] = useState<ModsView | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");
  const [actErr, setActErr] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(async () => {
    const res = await getServerMods(serverId);
    if (res.error) {
      setError(res.error);
      setView(null);
    } else {
      setView(res.view ?? null);
      setError(null);
    }
    setLoading(false);
  }, [serverId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  // Poll while a job is in flight or any mod is mid-install/remove.
  const applying =
    !!view?.busy ||
    !!view?.categories.some((c) => c.mods.some((m) => m.status === "INSTALLING" || m.status === "REMOVING"));
  useEffect(() => {
    if (!applying) return;
    const t = setInterval(() => void refresh(), 5000);
    return () => clearInterval(t);
  }, [applying, refresh]);

  const run = (fn: () => Promise<{ error?: string; ok?: boolean }>) => {
    setActErr(null);
    start(async () => {
      const r = await fn();
      if (r.error) setActErr(r.error);
      await refresh();
    });
  };

  const q = query.trim().toLowerCase();
  const cats = useMemo(() => {
    if (!view) return [];
    return view.categories
      .map((c) => ({
        category: c.category,
        mods: c.mods.filter(
          (m) =>
            !q ||
            m.name.toLowerCase().includes(q) ||
            m.category.toLowerCase().includes(q) ||
            (m.description ?? "").toLowerCase().includes(q)
        ),
      }))
      .filter((c) => c.mods.length > 0);
  }, [view, q]);

  if (loading) return <div className="card text-sm text-slate-400">Loading mods…</div>;
  if (error) return <div className="card text-sm text-slate-400">{error}</div>;
  if (!view) return null;

  const busy = view.busy || pending;

  return (
    <div className="space-y-5">
      <div className="card">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h2 className="text-lg font-semibold">Mods &amp; plugins</h2>
            <p className="mt-1 text-sm text-slate-400">
              One-click install onto your server.{" "}
              <span className="text-slate-300">{view.installedCount}</span> installed
              {view.variant ? (
                <>
                  {" "}
                  · showing mods for <span className="text-brand-300">{view.variant}</span>
                </>
              ) : null}
              .
            </p>
          </div>
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search mods…"
            className="input w-full max-w-xs"
          />
        </div>
        {view.busy && (
          <div className="mt-3 rounded-lg border border-amber-500/25 bg-amber-500/[0.06] px-3 py-2 text-xs text-amber-300">
            A change is being applied to your server — new installs are paused until it finishes.
          </div>
        )}
        {actErr && (
          <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/[0.07] px-3 py-2 text-xs text-red-300">
            {actErr}
          </div>
        )}
      </div>

      {cats.length === 0 ? (
        <div className="card text-sm text-slate-400">No mods match “{query}”.</div>
      ) : (
        cats.map((c) => (
          <div key={c.category} className="space-y-3">
            <h3 className="text-xs font-semibold uppercase tracking-[0.14em] text-slate-500">{c.category}</h3>
            <div className="grid gap-3 md:grid-cols-2">
              {c.mods.map((m) => (
                <ModCard
                  key={m.id}
                  mod={m}
                  busy={busy}
                  onInstall={() => run(() => installMod(serverId, m.id))}
                  onUninstall={() => run(() => uninstallMod(serverId, m.id))}
                />
              ))}
            </div>
          </div>
        ))
      )}
    </div>
  );
}

function ModCard({
