        <StatusPill status={status} />
      </div>

      <div className="mt-auto flex items-center gap-2">
        {installed ? (
          <button className="btn-secondary py-1.5 text-sm" disabled={busy} onClick={onUninstall}>
            Uninstall
          </button>
        ) : failed ? (
          <button className="btn-secondary py-1.5 text-sm" disabled={busy} onClick={onInstall}>
            Retry install
          </button>
        ) : inflight ? (
          <button className="btn-secondary py-1.5 text-sm" disabled>
            {status === "INSTALLING" ? "Installing…" : "Removing…"}
          </button>
        ) : (
          <button className="btn-primary py-1.5 text-sm" disabled={busy} onClick={onInstall}>
            Install
          </button>
        )}
      </div>
      {failed && mod.error && <p className="text-xs text-red-400">{mod.error}</p>}
    </div>
  );
}

function StatusPill({ status }: { status: string | null }) {
  if (status === "INSTALLED")
    return <span className="rounded-full bg-emerald-500/15 px-2 py-0.5 text-[11px] font-semibold text-emerald-300">Installed</span>;
  if (status === "INSTALLING" || status === "REMOVING")
    return <span className="rounded-full bg-amber-500/15 px-2 py-0.5 text-[11px] font-semibold text-amber-300">Working…</span>;
  if (status === "FAILED")
    return <span className="rounded-full bg-red-500/15 px-2 py-0.5 text-[11px] font-semibold text-red-300">Failed</span>;
  return null;
}

