  const refresh = useCallback(() => {
    listGameSchedules(serverId).then((r) => {
      if (r.ok) setRows(r.schedules);
      else setErr(r.error);
    });
  }, [serverId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  function add() {
    start(async () => {
      setErr(null);
      const r = await createGameSchedule(serverId, hour, minute, announce);
      if (!r.ok) setErr(r.error);
      else refresh();
    });
  }
  function toggle(row: ScheduleRow) {
    start(async () => {
      const r = await updateGameSchedule(row.id, { enabled: !row.enabled });
      if (!r.ok) setErr(r.error);
      else refresh();
    });
  }
  function remove(id: string) {
    start(async () => {
      const r = await deleteGameSchedule(id);
      if (!r.ok) setErr(r.error);
      else refresh();
    });
