              ))}
            </select>
            <span>:</span>
            <select className="input w-20" value={minute} onChange={(e) => setMinute(Number(e.target.value))}>
              {[0, 15, 30, 45].map((m) => (
                <option key={m} value={m}>
                  {String(m).padStart(2, "0")}
                </option>
              ))}
            </select>
          </span>
        </label>
        <label className="flex items-center gap-2 text-sm">
          <input type="checkbox" checked={announce} onChange={(e) => setAnnounce(e.target.checked)} />
          Warn players first
        </label>
        <button className="btn-primary" onClick={add} disabled={pending}>
          Add schedule
        </button>
      </div>

      {rows.length === 0 ? (
        <p className="mt-4 text-sm text-slate-400">No schedules yet.</p>
      ) : (
        <ul className="mt-4 divide-y divide-white/[0.06]">
          {rows.map((r) => (
            <li key={r.id} className="flex flex-wrap items-center justify-between gap-2 py-2.5 text-sm">
              <span className="flex items-center gap-3">
                <span className="font-mono">{hhmm(r.hour, r.minute)} UTC</span>
                <span className={`text-xs ${r.enabled ? "text-emerald-400" : "text-slate-500"}`}>
                  {r.enabled ? "enabled" : "paused"}
                </span>
                {r.announce && <span className="text-xs text-slate-500">warns players</span>}
                {r.enabled && r.nextRunAt && (
                  <span className="text-xs text-slate-500">next: {new Date(r.nextRunAt).toLocaleString()}</span>
                )}
              </span>
              <span className="flex gap-3">
                <button className="text-xs text-slate-400 hover:text-white" onClick={() => toggle(r)} disabled={pending}>
                  {r.enabled ? "Pause" : "Resume"}
                </button>
                <button className="text-xs text-red-400 hover:text-red-300" onClick={() => remove(r.id)} disabled={pending}>
                  Remove
                </button>
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

