"use client";

import { useState, useTransition } from "react";
import { serverAction } from "@/lib/actions";

export function ServerControls({
  serverId,
  status,
  busy,
}: {
  serverId: string;
  status: string;
  busy: boolean;
}) {
  const [pending, startTransition] = useTransition();
  // serverAction returns { error } for anything the customer can act on. Called
  // bare, the message was discarded; a thrown error became Next's redacted generic
  // page. Either way the specific, actionable text never reached the screen.
  const [error, setError] = useState<string | null>(null);
  const disabled = pending || busy;

  const run = (action: string, confirmMsg?: string) => {
    if (confirmMsg && !window.confirm(confirmMsg)) return;
    setError(null);
    startTransition(async () => {
      const res = await serverAction(serverId, action);
      if (res?.error) setError(res.error);
    });
  };

  return (
    <div className="flex flex-col gap-2">
      <div className="flex flex-wrap gap-2">
      {status !== "RUNNING" && (
        <button className="btn-primary" disabled={disabled} onClick={() => run("start")}>
          Start
        </button>
      )}
      {status === "RUNNING" && (
        <>
          <button className="btn-secondary" disabled={disabled} onClick={() => run("reboot")}>
            Reboot
          </button>
          <button className="btn-secondary" disabled={disabled} onClick={() => run("stop")}>
            Stop
          </button>
        </>
      )}
      <button
        className="btn-secondary"
        disabled={disabled}
        onClick={() =>
          run("reinstall", "Reinstall wipes ALL data on this VPS and redeploys the OS. Continue?")
        }
      >
        Reinstall
      </button>
      <button
        className="btn-danger"
        disabled={disabled}
        onClick={() =>
          run("delete", "Permanently delete this VPS and all its data? This cannot be undone.")
        }
      >
        Delete
      </button>
      </div>
      {error && (
        <p className="text-xs text-red-400" role="alert">
          {error}
        </p>
      )}
    </div>
  );
}
