  data,
  width = 120,
  height = 36,
  stroke = "#8a70fb",
  id,
}: {
  data: number[];
  width?: number;
  height?: number;
  stroke?: string;
  id: string;
}) {
  if (data.length === 0) return null;
  const pts = scale(data, width, height);
  const line = pathFrom(pts);
  const area = `${line} L${pts[pts.length - 1][0].toFixed(2)},${height} L${pts[0][0].toFixed(2)},${height} Z`;
  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
      <defs>
        <linearGradient id={`sg-${id}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={stroke} stopOpacity="0.35" />
          <stop offset="100%" stopColor={stroke} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={area} fill={`url(#sg-${id})`} />
      <path d={line} fill="none" stroke={stroke} strokeWidth="1.5" strokeLinecap="round" />
    </svg>
  );
}

export function AreaChart({
  series,
  width = 720,
  height = 220,
  id,
  yLabel,
  xLabels = [],
  maxY,
}: {
  series: { name: string; data: number[]; color: string }[];
  width?: number;
  height?: number;
  id: string;
  yLabel?: (v: number) => string;
  xLabels?: string[];
  maxY?: number;
}) {
  const all = series.flatMap((s) => s.data);
  if (all.length === 0) return <p className="text-sm text-slate-500">No data yet.</p>;
  const max = maxY ?? Math.max(...all, 1e-9);
  const padL = 46;
  const padB = 22;
  const cw = width - padL - 8;
  const ch = height - padB - 8;
  const gridLines = 4;

  return (
    <div className="w-full overflow-x-auto">
      <svg
        width="100%"
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="none"
        className="min-w-[480px]"
        style={{ height }}
      >
        <defs>
          {series.map((s, si) => (
            <linearGradient key={si} id={`ag-${id}-${si}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={s.color} stopOpacity="0.30" />
              <stop offset="100%" stopColor={s.color} stopOpacity="0" />
            </linearGradient>
          ))}
        </defs>
        {Array.from({ length: gridLines + 1 }, (_, i) => {
          const y = 8 + (ch / gridLines) * i;
          const v = max * (1 - i / gridLines);
          return (
            <g key={i}>
              <line x1={padL} x2={width - 8} y1={y} y2={y} stroke="rgba(255,255,255,0.05)" />
              <text x={padL - 8} y={y + 3.5} textAnchor="end" fontSize="10" fill="#64748b">
                {yLabel ? yLabel(v) : v.toFixed(0)}
              </text>
            </g>
          );
        })}
        {xLabels.map((l, i) => (
          <text
            key={i}
            x={padL + (cw / Math.max(xLabels.length - 1, 1)) * i}
            y={height - 6}
            textAnchor="middle"
            fontSize="10"
            fill="#64748b"
          >
            {l}
          </text>
        ))}
        {series.map((s, si) => {
          const pts: [number, number][] = s.data.map((v, i) => [
            padL + (i / Math.max(s.data.length - 1, 1)) * cw,
            8 + ch - (v / max) * ch,
          ]);
          const line = pathFrom(pts);
          const area = `${line} L${(padL + cw).toFixed(2)},${8 + ch} L${padL},${8 + ch} Z`;
          return (
            <g key={si}>
              <path d={area} fill={`url(#ag-${id}-${si})`} />
              <path d={line} fill="none" stroke={s.color} strokeWidth="2" strokeLinecap="round" />
            </g>
          );
        })}
