"use client";

import { useCallback, useEffect, useState } from "react";
import { AreaChart } from "@/components/ui/charts";

type Row = {
  time: number;
  cpu: number | null;
  mem: number | null;
  maxmem: number | null;
  netin: number | null;
  netout: number | null;
};

const TIMEFRAMES = [
  { key: "hour", label: "1h" },
  { key: "day", label: "24h" },
  { key: "week", label: "7d" },
  { key: "month", label: "30d" },
] as const;

function xLabelsFor(rows: Row[], tf: string): string[] {
  if (rows.length < 2) return [];
  const n = 6;
  const labels: string[] = [];
  for (let i = 0; i < n; i++) {
    const idx = Math.round((i / (n - 1)) * (rows.length - 1));
    const d = new Date(rows[idx].time * 1000);
    labels.push(
      tf === "hour" || tf === "day"
        ? `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`
        : `${String(d.getMonth() + 1).padStart(2, "0")}/${String(d.getDate()).padStart(2, "0")}`
    );
  }
  return labels;
}

