export async function getGamePlayers(
  serverId: string
): Promise<{ ok: true; players: Player[]; raw: string } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    if (spec.rcon !== "source" || !spec.listCommand)
      return { ok: false, error: `Player list is not available for ${spec.label}.` };
    const limited = throttle(user.id, "players", 40);
    if (limited) return { ok: false, error: limited };
    if (SANDBOX)
      return { ok: true, players: [{ name: "steve" }, { name: "alex" }], raw: "There are 2 of a max of 20 players online: steve, alex" };
    if (server.status !== "RUNNING")
      return { ok: false, error: "The player list is available only while the server is running." };
    const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, spec.listCommand!));
    if (!res.ok) return { ok: false, error: res.error };
    const parsed = parsePlayers(spec.family, res.response);
    return { ok: true, players: parsed.players, raw: parsed.raw };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

async function playerAction(serverId: string, playerId: string, kind: "kick" | "ban"): Promise<Result> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    const template = kind === "kick" ? spec.kickCommand : spec.banCommand;
    if (spec.rcon !== "source" || !template)
      return { ok: false, error: `${kind === "kick" ? "Kick" : "Ban"} is not available for ${spec.label}.` };
    const valid = validatePlayerId(playerId);
    if (!valid.ok) return { ok: false, error: valid.error };
    const limited = throttle(user.id, "player-action", 20);
    if (limited) return { ok: false, error: limited };
    if (SANDBOX) return { ok: true };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };

    const command = template.replace("%s", valid.id);
    await db.auditLog.create({
      data: { userId: user.id, action: `gameserver.${kind}`, detail: `${spec.family}: ${valid.id}` },
    });
    const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, command));
    return res.ok ? { ok: true } : { ok: false, error: res.error };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function kickPlayer(serverId: string, playerId: string): Promise<Result> {
  return playerAction(serverId, playerId, "kick");
}
export async function banPlayer(serverId: string, playerId: string): Promise<Result> {
  return playerAction(serverId, playerId, "ban");
}

