export async function submitBuild(
  serverId: string,
  prompt: string
): Promise<{ error?: string; buildId?: string }> {
  const user = await requireUser();

  // Feature flag: "Build with Claude" can be switched off platform-wide.
  if (!(await getSettingBool("feature_claude_builder", true))) {
    return { error: "Build with Claude is currently unavailable." };
  }

  const clean = (prompt ?? "").trim();
  if (clean.length < MIN_PROMPT_CHARS) {
    return { error: "Please describe what you'd like Claude to build (a sentence or two)." };
  }
  if (clean.length > MAX_PROMPT_CHARS) {
    return { error: `Prompt is too long (max ${MAX_PROMPT_CHARS} characters).` };
  }

  // BYOK gate: the owner must have an effective key (their own, or a platform fallback).
  const owner = await db.user.findUnique({
    where: { id: user.id },
    select: { anthropicKeyEnc: true },
  });
  if (!effectiveKeyFor(owner)) {
    return { error: "Add your Anthropic API key in Settings to use Build with AI." };
  }

  // Ownership: the server must belong to this user.
  const server = await db.server.findFirst({ where: { id: serverId, userId: user.id } });
  if (!server) return { error: "Server not found." };

