/**
 * Shared prop shapes for the premium game-server management panel
 * (components/customer/gamepanel/*). Kept in a plain module so the client shell,
 * header and tabs can all import the same types without pulling server code.
 */

export type HeaderStat = {
  /** current value, already scaled to its display unit */
  value: number;
  /** the ceiling for the meter (same unit as `value`) */
  max: number;
};

export type GameHeaderData = {
  /** customer-facing server name (label || name) */
  name: string;
  /** pretty game name, e.g. "Rust", "Minecraft" */
  gameLabel: string;
  /** raw ServerStatus (RUNNING, STOPPED, …) */
  status: string;
  running: boolean;
  /** ip:port players connect to, or null while provisioning */
  connect: string | null;
  /** short server id badge, e.g. "#srv_8f7a2c1d" */
  serverIdShort: string;
  node: string | null;
  location: string | null;
  players: { online: number; max: number | null };
  /** CPU percent 0-100 */
  cpuPct: number;
  /** memory in bytes */
  mem: { usedBytes: number; maxBytes: number };
  /** disk in GB */
  disk: { usedGB: number; maxGB: number };
  /** network throughput, MB/s (null when unknown) */
  net: { inMbps: number | null; outMbps: number | null };
  uptimeLabel: string;
  createdLabel: string;
  nextRestartLabel: string | null;
  /** power controls are usable (VM steady + not busy) */
  canControl: boolean;
};

export type PanelTab =
  | "overview"
  | "console"
  | "files"
  | "mods"
  | "plugins"
  | "backups"
  | "players"
  | "settings"
  | "activity";

"use client";

import { useEffect, useRef, useState, useTransition } from "react";
import { gamePower } from "@/lib/actions-game-control";
import { Sparkline } from "@/components/ui/charts";
import { fmtBytes } from "@/components/ui/primitives";
import type { GameHeaderData } from "./types";

/**
 * Persistent, always-visible header for the game-server panel.
 *
 * Shows identity + live vitals (players / CPU / RAM / disk) with glowing status
 * and animated micro-graphs, and keeps Connect / Restart / Stop reachable from
 * every tab. Power buttons call the ownership-guarded `gamePower` action; the
 * micro-graphs poll /api/metrics for shape (values themselves come from the
 * server-rendered snapshot, so the numbers are always truthful).
 */

const STATUS_TONE: Record<string, { dot: string; glow: string; label: string }> = {
  RUNNING: { dot: "#34d399", glow: "0 0 10px 1px rgba(52,211,153,0.7)", label: "Online" },
  STOPPED: { dot: "#f87171", glow: "0 0 10px 1px rgba(248,113,113,0.6)", label: "Offline" },
  SUSPENDED: { dot: "#fbbf24", glow: "0 0 10px 1px rgba(251,191,36,0.6)", label: "Suspended" },
  PROVISIONING: { dot: "#60a5fa", glow: "0 0 10px 1px rgba(96,165,250,0.7)", label: "Deploying" },
  PENDING: { dot: "#60a5fa", glow: "0 0 10px 1px rgba(96,165,250,0.7)", label: "Deploying" },
  ERROR: { dot: "#f87171", glow: "0 0 10px 1px rgba(248,113,113,0.6)", label: "Error" },
};

/** Deterministic gentle wave around a base value — a placeholder trend that
 *  always looks alive even before RRD history is available. */
function seedWave(base: number, seed: number): number[] {
  const out: number[] = [];
  for (let i = 0; i < 24; i++) {
    const n = Math.sin((i + seed) * 0.7) * 0.12 + Math.sin((i + seed) * 1.9) * 0.05;
    out.push(Math.max(0, base * (1 + n)));
  }
  return out;
}

export function GamePanelHeader({ serverId, data }: { serverId: string; data: GameHeaderData }) {
  const [copied, setCopied] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const [cpuSeries, setCpuSeries] = useState<number[]>(() => seedWave(data.cpuPct, 1));
  const [memSeries, setMemSeries] = useState<number[]>(() =>
    seedWave(data.mem.maxBytes ? (data.mem.usedBytes / data.mem.maxBytes) * 100 : 40, 5)
  );
  const copyTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const tone = STATUS_TONE[data.status] ?? STATUS_TONE.STOPPED;
  const memPct = data.mem.maxBytes ? (data.mem.usedBytes / data.mem.maxBytes) * 100 : 0;
  const diskPct = data.disk.maxGB ? (data.disk.usedGB / data.disk.maxGB) * 100 : 0;

  // Poll real RRD history for graph shape (values shown remain the truthful
  // server snapshot). Silently falls back to the seeded wave on any failure.
  useEffect(() => {
    if (!data.running) return;
    let alive = true;
    const load = async () => {
      try {
        const res = await fetch(`/api/metrics?serverId=${serverId}&tf=hour`, { cache: "no-store" });
        if (!res.ok) return;
        const json: { data?: { cpu: number | null; mem: number | null; maxmem: number | null }[] } =
          await res.json();
        const rows = (json.data ?? []).slice(-24);
        if (!alive || rows.length < 3) return;
        setCpuSeries(rows.map((r) => (r.cpu ?? 0) * 100));
        setMemSeries(rows.map((r) => (r.mem && r.maxmem ? (r.mem / r.maxmem) * 100 : 0)));
      } catch {
        /* keep the seeded wave */
      }
    };
    void load();
    const t = setInterval(load, 15000);
    return () => {
      alive = false;
      clearInterval(t);
    };
  }, [serverId, data.running]);

  function copyConnect() {
    if (!data.connect) return;
    void navigator.clipboard?.writeText(data.connect);
    setCopied(true);
    if (copyTimer.current) clearTimeout(copyTimer.current);
    copyTimer.current = setTimeout(() => setCopied(false), 1600);
  }

  function power(action: "restart" | "stop") {
    if (action === "stop" && !window.confirm("Stop the game server? Players will be disconnected.")) return;
    setErr(null);
    start(async () => {
      const r = await gamePower(serverId, action);
      if (!r.ok) setErr(r.error);
    });
  }

  const disabled = pending || !data.canControl || !data.running;

  return (
    <div className="relative overflow-hidden rounded-3xl border border-white/[0.07] bg-gradient-to-br from-navy-900/90 via-navy-950/80 to-navy-900/70 p-6 shadow-[0_20px_60px_-30px_rgba(111,71,245,0.5)] backdrop-blur-xl">
      {/* ambient aura */}
      <div
        aria-hidden
        className="pointer-events-none absolute -right-24 -top-24 h-64 w-64 rounded-full opacity-40 blur-3xl"
        style={{ background: "radial-gradient(circle, rgba(111,71,245,0.5), transparent 70%)" }}
      />
      <div className="relative flex flex-wrap items-start justify-between gap-6">
        {/* Identity */}
        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-3">
            <div
              className="flex h-12 w-12 items-center justify-center rounded-2xl border border-white/10 bg-gradient-to-br from-brand-500/30 to-accent-blue/20 text-lg font-bold text-white"
              aria-hidden
            >
              {data.gameLabel.slice(0, 2).toUpperCase()}
            </div>
            <div className="min-w-0">
              <h1 className="truncate text-2xl font-bold tracking-tight text-white">{data.name}</h1>
              <div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-slate-400">
                <span className="inline-flex items-center gap-1.5 font-medium">
                  <span
                    className="inline-block h-2 w-2 rounded-full"
                    style={{ background: tone.dot, boxShadow: tone.glow }}
                  />
                  <span className="text-slate-200">{tone.label}</span>
                </span>
                {data.connect && (
                  <button
                    onClick={copyConnect}
                    className="rounded-md border border-white/10 bg-navy-950/70 px-2 py-0.5 font-mono text-[11px] text-slate-300 transition-colors hover:border-brand-400/50 hover:text-white"
                    title="Copy connect address"
                  >
                    {copied ? "copied ✓" : data.connect}
                  </button>
                )}
                {data.location && <span>· {data.location}</span>}
                <span className="font-mono text-slate-500">· {data.serverIdShort}</span>
              </div>
            </div>
          </div>
        </div>

        {/* Vitals + actions */}
        <div className="flex flex-1 flex-wrap items-center justify-end gap-4">
          <div className="flex flex-wrap items-center gap-5">
            <Vital label="Players" value={`${data.players.online}${data.players.max ? ` / ${data.players.max}` : ""}`}>
              <div className="mt-1 h-1 w-16 overflow-hidden rounded-full bg-white/10">
                <div
                  className="h-full rounded-full bg-gradient-to-r from-accent-cyan to-brand-400"
                  style={{ width: `${data.players.max ? Math.min(100, (data.players.online / data.players.max) * 100) : 0}%` }}
                />
              </div>
            </Vital>
            <Vital label="CPU" value={`${data.cpuPct.toFixed(0)}%`}>
              <Sparkline id={`hdr-cpu-${serverId}`} data={cpuSeries} width={72} height={26} stroke="#8a70fb" />
            </Vital>
            <Vital label="RAM" value={`${fmtBytes(data.mem.usedBytes)} / ${fmtBytes(data.mem.maxBytes)}`}>
              <Sparkline id={`hdr-mem-${serverId}`} data={memSeries} width={72} height={26} stroke="#3b82f6" />
            </Vital>
            <Vital label="Disk" value={`${data.disk.usedGB.toFixed(1)} / ${data.disk.maxGB} GB`}>
              <div className="mt-1 h-1 w-16 overflow-hidden rounded-full bg-white/10">
                <div className="h-full rounded-full bg-gradient-to-r from-amber-400 to-orange-500" style={{ width: `${Math.min(100, diskPct)}%` }} />
              </div>
            </Vital>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={copyConnect}
              disabled={!data.connect}
              className="btn-primary disabled:opacity-40"
              title={data.connect ? "Copy the connect address" : "Connect address not ready"}
            >
              {copied ? "Copied ✓" : "Connect"}
            </button>
            <button onClick={() => power("restart")} disabled={disabled} className="btn-secondary disabled:opacity-40">
              Restart
            </button>
            <button onClick={() => power("stop")} disabled={disabled} className="btn-danger disabled:opacity-40">
              Stop
            </button>
          </div>
        </div>
      </div>

      {err && (
        <p className="relative mt-3 text-xs text-red-400" role="alert">
          {err}
        </p>
      )}
    </div>
  );
}

function Vital({ label, value, children }: { label: string; value: string; children?: React.ReactNode }) {
  return (
    <div className="min-w-[72px]">
      <p className="text-[10px] font-semibold uppercase tracking-[0.14em] text-slate-500">{label}</p>
      <p className="mt-0.5 text-sm font-semibold text-white">{value}</p>
      {children}
    </div>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import { GamePanelHeader } from "./GamePanelHeader";
import { GameOverview } from "./GameOverview";
import { GameConsole } from "./GameConsole";
import { ModStore } from "./ModStore";
import { GamePlayers } from "./GamePlayers";
import type { GameHeaderData, PanelTab } from "./types";

/**
 * Premium per-game-server management panel — a total overhaul of the generic
 * VPS detail view for game servers. A persistent vitals header sits above a tab
 * strip: Overview, Console, Files, Mods (Mod Store), Plugins, Backups, Players,
 * Settings, Activity.
 *
 * Client tabs (Overview / Console / Mods / Plugins / Players) render here from
 * `serverId`; the heavier server-rendered surfaces (Files, Backups, Settings,
 * Activity) are passed in as slots so their DB/hypervisor reads stay on the
 * server. Every live action is wired to the existing ownership-guarded actions
 * in lib/actions-game-control.ts / lib/actions-mods.ts.
 */

const TABS: { key: PanelTab; label: string }[] = [
  { key: "overview", label: "Overview" },
  { key: "console", label: "Console" },
  { key: "files", label: "Files" },
  { key: "mods", label: "Mods" },
  { key: "plugins", label: "Plugins" },
  { key: "backups", label: "Backups" },
  { key: "players", label: "Players" },
  { key: "settings", label: "Settings" },
  { key: "activity", label: "Activity" },
];

export function GameServerPanel({
  serverId,
  gameFamily,
  header,
  filesPanel,
  backupsPanel,
  settingsPanel,
  activityPanel,
  initialTab,
}: {
  serverId: string;
  gameFamily: string;
  header: GameHeaderData;
  filesPanel: ReactNode;
  backupsPanel: ReactNode;
  settingsPanel: ReactNode;
  activityPanel: ReactNode;
  initialTab?: string;
}) {
  const keys = TABS.map((t) => t.key as string);
  const [tab, setTab] = useState<PanelTab>(
    initialTab && keys.includes(initialTab.toLowerCase()) ? (initialTab.toLowerCase() as PanelTab) : "overview"
  );

  const go = (t: PanelTab) => {
    setTab(t);
    window.history.replaceState(null, "", `?tab=${t}`);
    if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" });
  };

  return (
    <div className="space-y-6">
      <GamePanelHeader serverId={serverId} data={header} />

      <div className="sticky top-2 z-10 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/80 p-1 backdrop-blur-xl">
        {TABS.map((t) => {
          const active = tab === t.key;
          return (
            <button
              key={t.key}
              type="button"
              onClick={() => go(t.key)}
              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
                active
                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
              }`}
            >
              {t.label}
            </button>
          );
        })}
      </div>

      <div className="animate-fade-up">
        {tab === "overview" && <GameOverview serverId={serverId} gameFamily={gameFamily} data={header} onNavigate={go} />}
        {tab === "console" && <GameConsole serverId={serverId} running={header.running} />}
        {tab === "files" && filesPanel}
        {tab === "mods" && <ModStore serverId={serverId} scope="mods" onOpenPlugins={() => go("plugins")} />}
        {tab === "plugins" && <ModStore serverId={serverId} scope="plugins" onOpenPlugins={() => go("mods")} />}
        {tab === "backups" && backupsPanel}
        {tab === "players" && <GamePlayers serverId={serverId} running={header.running} playersMax={header.players.max} />}
        {tab === "settings" && settingsPanel}
        {tab === "activity" && activityPanel}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { MeterBar } from "@/components/ui/charts";
