import { getGamePlayers } from "@/lib/actions-game-control";
import { GameBuildAI } from "./GameBuildAI";
import type { GameHeaderData, PanelTab } from "./types";

/**
 * Overview tab — the at-a-glance surface: identity + status, resource usage,
 * quick actions that jump to the relevant tab, live resource graphs (reusing the
 * VPS MetricsPanel), a connected-player peek, and the in-server "Build with AI"
 * assistant. All numbers come from the truthful server snapshot in `data`; the
 * player peek and graphs load live.
 */

type QuickAction = { label: string; tab: PanelTab; tone: "brand" | "danger" | "slate" };

const QUICK: QuickAction[] = [
  { label: "Restart", tab: "console", tone: "brand" },
  { label: "Stop", tab: "console", tone: "danger" },
  { label: "Console", tab: "console", tone: "slate" },
  { label: "Files", tab: "files", tone: "slate" },
  { label: "Mods", tab: "mods", tone: "slate" },
  { label: "Backups", tab: "backups", tone: "slate" },
];

export function GameOverview({
  serverId,
  gameFamily,
  data,
  onNavigate,
}: {
  serverId: string;
  gameFamily: string;
  data: GameHeaderData;
  onNavigate: (t: PanelTab) => void;
}) {
  const [players, setPlayers] = useState<{ name: string; extra?: string }[] | null>(null);

