      alive = false;
    };
  }, [serverId, data.running]);

  const memPct = data.mem.maxBytes ? (data.mem.usedBytes / data.mem.maxBytes) * 100 : 0;
  const diskPct = data.disk.maxGB ? (data.disk.usedGB / data.disk.maxGB) * 100 : 0;

  return (
    <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
