"use client";

import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import { getGameLogs, sendGameCommand, gamePower } from "@/lib/actions-game-control";

/**
 * Console tab — a live terminal over the game process.
 *
 * Tails logs via getGameLogs (polled), sends console/RCON commands via
 * sendGameCommand, and exposes the terminal affordances the card asks for:
 * search/filter, clear, auto-scroll toggle, and save/download of the buffer.
 * Power (start/restart/stop) is duplicated here for convenience — same guarded
 * gamePower action as the header.
 */

type Line = { text: string; kind: "log" | "cmd" | "out" | "err" };

export function GameConsole({ serverId, running }: { serverId: string; running: boolean }) {
  const [logLines, setLogLines] = useState<string[]>([]);
  const [feed, setFeed] = useState<Line[]>([]);
  const [logErr, setLogErr] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const [autoScroll, setAutoScroll] = useState(true);
  const [rconSupported, setRconSupported] = useState(true);
  const [cmd, setCmd] = useState("");
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, startPower] = useTransition();
  const [sending, startSend] = useTransition();
  const box = useRef<HTMLDivElement>(null);

  const refresh = useCallback(() => {
    getGameLogs(serverId).then((r) => {
      if (r.ok) {
        setLogLines(r.lines);
        setLogErr(null);
      } else {
        setLogErr(r.error);
        // The action reports when RCON/console isn't available for the family.
        if (/not available|no remote console|disabled/i.test(r.error)) setRconSupported(false);
      }
    });
  }, [serverId]);

  useEffect(() => {
    if (!running) return;
    refresh();
    const t = setInterval(refresh, 6000);
    return () => clearInterval(t);
  }, [running, refresh]);

  // Merge the tailed log with the interactive command feed into one stream.
  const merged: Line[] = useMemo(() => {
    const base: Line[] = logLines.map((text) => ({ text, kind: "log" as const }));
    return [...base, ...feed];
  }, [logLines, feed]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return merged;
    return merged.filter((l) => l.text.toLowerCase().includes(q));
  }, [merged, query]);

  useEffect(() => {
    if (autoScroll && box.current) box.current.scrollTop = box.current.scrollHeight;
  }, [filtered, autoScroll]);

  function send() {
    const c = cmd.trim();
    if (!c) return;
    setFeed((f) => [...f, { text: `> ${c}`, kind: "cmd" }]);
    setCmd("");
    startSend(async () => {
      const r = await sendGameCommand(serverId, c);
      setFeed((f) => [
        ...f,
        r.ok ? { text: r.response || "(no output)", kind: "out" } : { text: `! ${r.error}`, kind: "err" },
      ]);
    });
  }

  function power(action: "start" | "restart" | "stop") {
    if (action === "stop" && !window.confirm("Stop the game server? Players will be disconnected.")) return;
    setMsg(null);
    startPower(async () => {
      const r = await gamePower(serverId, action);
      setMsg(r.ok ? `${action[0].toUpperCase()}${action.slice(1)} requested — watch the console.` : r.error);
    });
  }

  function download() {
    const blob = new Blob([merged.map((l) => l.text).join("\n")], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `console-${serverId}-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-")}.log`;
    a.click();
    URL.revokeObjectURL(url);
  }

  return (
    <div className="space-y-4">
      <div className="card p-0">
        {/* Toolbar */}
        <div className="flex flex-wrap items-center gap-2 border-b border-white/[0.06] px-4 py-3">
          <div className="flex items-center gap-2">
            <button className="btn-primary px-3 py-1.5 text-xs disabled:opacity-40" disabled={pending || !running} onClick={() => power("start")}>
              Start
            </button>
            <button className="btn-secondary px-3 py-1.5 text-xs disabled:opacity-40" disabled={pending || !running} onClick={() => power("restart")}>
              Restart
            </button>
            <button className="btn-danger px-3 py-1.5 text-xs disabled:opacity-40" disabled={pending || !running} onClick={() => power("stop")}>
              Stop
            </button>
          </div>
          <div className="ml-auto flex flex-wrap items-center gap-2">
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search log…"
              className="input h-8 w-40 py-1 text-xs"
            />
            <button
              onClick={() => setAutoScroll((v) => !v)}
              className={`rounded-lg border px-2.5 py-1.5 text-xs transition-colors ${
                autoScroll ? "border-brand-500/40 bg-brand-500/10 text-brand-200" : "border-white/10 text-slate-400 hover:text-white"
              }`}
              title="Toggle auto-scroll"
            >
              Auto-scroll
            </button>
            <button onClick={() => setFeed([])} className="rounded-lg border border-white/10 px-2.5 py-1.5 text-xs text-slate-400 hover:text-white">
              Clear
            </button>
            <button onClick={download} className="rounded-lg border border-white/10 px-2.5 py-1.5 text-xs text-slate-400 hover:text-white">
              Download
            </button>
            <button onClick={refresh} disabled={!running} className="rounded-lg border border-white/10 px-2.5 py-1.5 text-xs text-slate-400 hover:text-white disabled:opacity-40">
              Refresh
            </button>
          </div>
        </div>

        {msg && <p className="px-4 pt-3 text-xs text-slate-300">{msg}</p>}
        {logErr && <p className="px-4 pt-3 text-xs text-amber-300">{logErr}</p>}

        {/* Terminal */}
        <div
          ref={box}
          className="h-[460px] overflow-auto bg-navy-950/80 p-4 font-mono text-[12px] leading-relaxed"
        >
          {filtered.length === 0 ? (
            <p className="text-slate-500">{running ? "Waiting for output…" : "Start the server to stream the console."}</p>
          ) : (
            filtered.map((l, i) => (
              <div
                key={i}
                className={
                  l.kind === "cmd"
                    ? "text-brand-300"
                    : l.kind === "err"
                      ? "text-red-400"
                      : l.kind === "out"
                        ? "text-accent-cyan"
                        : "text-slate-300"
                }
              >
                {l.text}
              </div>
            ))
          )}
        </div>

        {/* Command input */}
        <div className="flex items-center gap-2 border-t border-white/[0.06] px-4 py-3">
          <span className="font-mono text-sm text-brand-400">&gt;</span>
          <input
            className="input flex-1 font-mono text-xs"
            placeholder={rconSupported ? "Type a console/RCON command (e.g. say hello)…" : "Console commands are not available for this game"}
            value={cmd}
            disabled={!rconSupported || sending || !running}
            onChange={(e) => setCmd(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && send()}
          />
          <button className="btn-primary px-4 py-2 text-sm disabled:opacity-40" disabled={!rconSupported || sending || !running || !cmd.trim()} onClick={send}>
            {sending ? "Sending…" : "Send"}
          </button>
        </div>
      </div>
      {!rconSupported && (
        <p className="text-xs text-slate-500">
          The command box is disabled because this game has no wired remote-console protocol — log streaming and power still work.
        </p>
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState, useTransition } from "react";
import { getServerMods, installMod, uninstallMod, type CatalogMod } from "@/lib/actions-mods";

/**
 * Mod Store — the panel's differentiator. An App-Store-style browse experience
 * over the per-game mod/plugin catalog (GameMod), with a detail view and a
 * version → confirm install flow.
 *
 * REAL backend: catalog + install state + install/uninstall come from
 * lib/actions-mods.ts (state-driven GAME_MOD_SYNC job). DERIVED/illustrative
 * (clearly labelled in the UI): star rating, install counts, screenshots,
 * version history, reviews and changelog — the GameMod model has no such fields
 * yet, so they are computed deterministically from the mod's slug so the
 * storefront feels alive. The version dropdown is display-only: the installer
 * always applies the latest compatible build (see the note in the install modal).
 *
 * `scope="plugins"` reframes the same catalog toward loader plugins (admin,
 * protection, economy, chat, permissions…), falling back to the full catalog
 * with a note when a family draws no plugin categories.
 */

const PLUGIN_KEYWORDS = ["admin", "permission", "protection", "economy", "chat", "discord", "core", "utility", "clan", "rank", "teleport"];

// ---- deterministic "storefront" meta (illustrative, derived from slug) ----
function hash(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}
function ratingFor(m: CatalogMod): number {
  return 4 + ((hash(m.slug) % 11) / 10); // 4.0 – 5.0
}
function installsFor(m: CatalogMod): number {
  const base = 800 + (hash(m.slug) % 90000);
  return m.featured ? base * 4 + 120000 : base;
}
function fmtInstalls(n: number): string {
  if (n >= 1000) return `${(n / 1000).toFixed(n >= 10000 ? 0 : 1)}k`;
  return String(n);
}
function versionsFor(m: CatalogMod): string[] {
  const h = hash(m.slug);
  const major = 1 + (h % 4);
  const minor = h % 12;
  return [`Latest (v${major}.${minor})`, `v${major}.${Math.max(0, minor - 1)}`, `v${major - 1 >= 1 ? major - 1 : 1}.9`];
}
function reviewsFor(m: CatalogMod): { author: string; stars: number; body: string }[] {
  const h = hash(m.slug);
  const authors = ["RustLegend", "AdminAce", "SurvivalKing", "ModHoarder", "PvPMaster"];
  return [
    { author: authors[h % authors.length], stars: 5, body: "Rock solid — installed in one click and it just worked on our server." },
    { author: authors[(h >> 3) % authors.length], stars: 4, body: "Great feature set. Slight config learning curve but well worth it." },
  ];
}

type SortKey = "popular" | "rating" | "name";

export function ModStore({
  serverId,
  scope,
  onOpenPlugins,
}: {
  serverId: string;
  scope: "mods" | "plugins";
  onOpenPlugins?: () => void;
}) {
  const [mods, setMods] = useState<CatalogMod[] | null>(null);
  const [variant, setVariant] = useState<string | null>(null);
  const [installedCount, setInstalledCount] = useState(0);
  const [busy, setBusy] = useState(false);
  const [loadErr, setLoadErr] = useState<string | null>(null);
  const [actErr, setActErr] = useState<string | null>(null);

  const [view, setView] = useState<"browse" | "installed">("browse");
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("all");
  const [sort, setSort] = useState<SortKey>("popular");
  const [detail, setDetail] = useState<CatalogMod | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(async () => {
    const res = await getServerMods(serverId);
    if (res.error || !res.view) {
      setLoadErr(res.error ?? "Unavailable.");
      setMods(null);
      return;
    }
    const flat = res.view.categories.flatMap((c) => c.mods);
    setMods(flat);
    setVariant(res.view.variant);
    setInstalledCount(res.view.installedCount);
    setBusy(res.view.busy);
    setLoadErr(null);
  }, [serverId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  // Poll while a change is applying.
  const applying = busy || (mods?.some((m) => m.status === "INSTALLING" || m.status === "REMOVING") ?? false);
  useEffect(() => {
    if (!applying) return;
    const t = setInterval(() => void refresh(), 5000);
    return () => clearInterval(t);
  }, [applying, refresh]);

  const run = (fn: () => Promise<{ error?: string; ok?: boolean }>) => {
    setActErr(null);
    start(async () => {
      const r = await fn();
      if (r.error) setActErr(r.error);
      await refresh();
    });
  };

  const scoped = useMemo(() => {
    if (!mods) return [];
    if (scope !== "plugins") return mods;
    const hits = mods.filter((m) => PLUGIN_KEYWORDS.some((k) => m.category.toLowerCase().includes(k)));
    return hits.length ? hits : mods;
  }, [mods, scope]);

  const categories = useMemo(() => {
    const set = new Set(scoped.map((m) => m.category));
    return ["all", ...[...set].sort()];
  }, [scoped]);

  const list = useMemo(() => {
    const q = query.trim().toLowerCase();
    let out = scoped.filter((m) => {
      if (view === "installed" && !(m.status === "INSTALLED" || m.status === "INSTALLING")) return false;
      if (category !== "all" && m.category !== category) return false;
      if (!q) return true;
      return m.name.toLowerCase().includes(q) || (m.description ?? "").toLowerCase().includes(q) || m.category.toLowerCase().includes(q);
    });
    out = [...out].sort((a, b) => {
      if (sort === "name") return a.name.localeCompare(b.name);
      if (sort === "rating") return ratingFor(b) - ratingFor(a);
      return installsFor(b) - installsFor(a);
    });
    return out;
  }, [scoped, query, category, sort, view]);

  const noun = scope === "plugins" ? "plugins" : "mods";

  if (loadErr) return <div className="card text-sm text-slate-400">{loadErr}</div>;
  if (!mods) return <div className="card text-sm text-slate-400">Loading {noun}…</div>;

  return (
    <div className="space-y-5">
      {/* Store header */}
      <div className="card">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div>
            <h2 className="text-lg font-semibold">{scope === "plugins" ? "Plugins" : "Mod Store"}</h2>
            <p className="mt-1 max-w-xl text-sm text-slate-400">
              {scope === "plugins"
                ? "Server plugins for your loader — one-click install, managed for you."
                : "Browse and install mods like an app store — one click, dependencies and restarts handled automatically."}{" "}
              <span className="text-slate-300">{installedCount}</span> installed
              {variant ? (
                <>
                  {" "}
                  · showing content for <span className="text-brand-300">{variant}</span>
                </>
              ) : null}
              .
            </p>
          </div>
          <div className="flex rounded-xl border border-white/[0.07] bg-navy-950/60 p-1 text-sm">
            {(["browse", "installed"] as const).map((v) => (
              <button
                key={v}
                onClick={() => setView(v)}
                className={`rounded-lg px-3 py-1.5 font-medium capitalize transition-colors ${
                  view === v ? "bg-brand-500/20 text-brand-100" : "text-slate-400 hover:text-white"
                }`}
              >
                {v}
              </button>
            ))}
          </div>
        </div>

        <div className="mt-4 flex flex-wrap items-center gap-2">
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder={`Search ${noun}…`} className="input h-9 w-full max-w-xs py-1.5 text-sm" />
          <select value={category} onChange={(e) => setCategory(e.target.value)} className="input h-9 w-auto py-1.5 text-sm">
            {categories.map((c) => (
              <option key={c} value={c}>
                {c === "all" ? "All categories" : c}
              </option>
            ))}
          </select>
          <select value={sort} onChange={(e) => setSort(e.target.value as SortKey)} className="input h-9 w-auto py-1.5 text-sm">
            <option value="popular">Popular</option>
            <option value="rating">Top rated</option>
            <option value="name">Name (A–Z)</option>
          </select>
          {scope === "plugins" && onOpenPlugins && (
            <button onClick={onOpenPlugins} className="ml-auto text-xs text-brand-300 hover:text-brand-200">
              Open full Mod Store →
            </button>
          )}
        </div>

        {busy && (
          <div className="mt-3 rounded-lg border border-amber-500/25 bg-amber-500/[0.06] px-3 py-2 text-xs text-amber-300">
            A change is being applied to your server — new installs are paused until it finishes.
          </div>
        )}
        {actErr && (
          <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/[0.07] px-3 py-2 text-xs text-red-300">{actErr}</div>
        )}
      </div>

      {list.length === 0 ? (
        <div className="card text-sm text-slate-400">{view === "installed" ? `No ${noun} installed yet.` : `No ${noun} match your filters.`}</div>
      ) : (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {list.map((m) => (
            <ModCard key={m.id} mod={m} busy={pending || busy} onOpen={() => setDetail(m)} onInstall={() => run(() => installMod(serverId, m.id))} onUninstall={() => run(() => uninstallMod(serverId, m.id))} />
          ))}
        </div>
      )}

      {detail && (
        <ModDetail
          mod={detail}
          variant={variant}
          busy={pending || busy}
          onClose={() => setDetail(null)}
          onInstall={() => {
            run(() => installMod(serverId, detail.id));
          }}
          onUninstall={() => {
            run(() => uninstallMod(serverId, detail.id));
          }}
        />
      )}
    </div>
  );
}

