"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import { getGamePlayers, kickPlayer, banPlayer } from "@/lib/actions-game-control";
import type { Player } from "@/lib/game-control";

/**
 * Players tab — connected-player management.
 *
 * REAL backend: the online list + kick/ban run over the family's RCON via
 * getGamePlayers / kickPlayer / banPlayer (SANDBOX returns synthetic players).
 * The Bans / Whitelist / Operators / History sub-views are marked "not yet
 * wired" — there is no persistence for them yet, and they are labelled as such
 * rather than faked.
 */

const SUB = [
  { key: "online", label: "Online" },
  { key: "history", label: "History" },
  { key: "bans", label: "Bans" },
  { key: "whitelist", label: "Whitelist" },
  { key: "ops", label: "Operators" },
] as const;

export function GamePlayers({ serverId, running, playersMax }: { serverId: string; running: boolean; playersMax: number | null }) {
  const [tab, setTab] = useState<(typeof SUB)[number]["key"]>("online");

  return (
    <div className="space-y-5">
      <div className="flex flex-wrap gap-1.5">
        {SUB.map((s) => {
          const active = tab === s.key;
          return (
            <button
              key={s.key}
              onClick={() => setTab(s.key)}
              className={`rounded-xl px-3.5 py-1.5 text-sm font-medium transition-colors ${
                active ? "bg-white/[0.08] text-white ring-1 ring-inset ring-brand-500/40" : "text-slate-400 hover:bg-white/[0.04] hover:text-white"
              }`}
            >
              {s.label}
            </button>
          );
        })}
      </div>

      {tab === "online" ? (
        <OnlinePlayers serverId={serverId} running={running} playersMax={playersMax} />
      ) : (
        <NotWired
          title={SUB.find((s) => s.key === tab)!.label}
          note={
            tab === "history"
              ? "Session history (joins, leaves, playtime) will appear here once player-event logging is enabled for game servers."
              : tab === "bans"
                ? "A persistent ban list with reasons and expiry is coming. For now, use Ban on the Online tab (applied live over RCON)."
                : tab === "whitelist"
                  ? "Whitelist management (add/remove, enforce) is coming. Manage it via server config in the Files tab for now."
                  : "Operator/admin promotion is coming. Grant OP via console commands in the Console tab for now."
          }
        />
      )}
    </div>
  );
}

function OnlinePlayers({ serverId, running, playersMax }: { serverId: string; running: boolean; playersMax: number | null }) {
  const [players, setPlayers] = useState<Player[] | null>(null);
  const [supported, setSupported] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(() => {
    start(async () => {
      const r = await getGamePlayers(serverId);
      if (r.ok) {
        setPlayers(r.players);
        setErr(null);
      } else {
        setErr(r.error);
        if (/not available/i.test(r.error)) setSupported(false);
      }
    });
  }, [serverId]);

  useEffect(() => {
    if (running) refresh();
  }, [running, refresh]);

  function act(kind: "kick" | "ban", id: string) {
    if (kind === "ban" && !window.confirm(`Ban ${id}? They will be disconnected and blocked.`)) return;
    start(async () => {
      const r = kind === "kick" ? await kickPlayer(serverId, id) : await banPlayer(serverId, id);
      if (!r.ok) setErr(r.error);
      else refresh();
    });
  }

  if (!supported) return <div className="card text-sm text-slate-400">Player management is not available for this game.</div>;

  return (
    <div className="card">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="font-semibold">Connected players</h3>
          <p className="mt-0.5 text-sm text-slate-400">
            {players ? players.length : 0}
            {playersMax ? ` / ${playersMax}` : ""} online
          </p>
        </div>
        <button className="text-xs text-slate-400 hover:text-white disabled:opacity-40" onClick={refresh} disabled={pending || !running}>
          Refresh
        </button>
      </div>
      {err && <p className="mt-3 text-sm text-amber-300">{err}</p>}
      {!running ? (
        <p className="mt-4 text-sm text-slate-500">Start the server to see connected players.</p>
      ) : players === null ? (
        <p className="mt-4 text-sm text-slate-500">Loading…</p>
      ) : players.length === 0 ? (
        <p className="mt-4 text-sm text-slate-500">No players connected.</p>
      ) : (
        <ul className="mt-4 divide-y divide-white/[0.06]">
          {players.map((p) => (
            <li key={p.name} className="flex items-center justify-between py-2.5">
              <span className="flex items-center gap-2.5 text-sm">
                <span className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-brand-500/40 to-accent-blue/30 text-[11px] font-bold text-white">
                  {p.name.slice(0, 2).toUpperCase()}
                </span>
                <span className="font-medium text-slate-100">{p.name}</span>
                {p.extra && <span className="text-xs text-slate-500">{p.extra}</span>}
              </span>
              <span className="flex gap-3">
                <button className="text-xs text-slate-400 hover:text-white" onClick={() => act("kick", p.name)} disabled={pending}>
                  Kick
                </button>
                <button className="text-xs text-red-400 hover:text-red-300" onClick={() => act("ban", p.name)} disabled={pending}>
                  Ban
                </button>
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function NotWired({ title, note }: { title: string; note: string }) {
  return (
    <div className="card">
      <div className="flex items-center gap-2">
        <h3 className="font-semibold">{title}</h3>
        <span className="rounded-full border border-amber-500/25 bg-amber-500/[0.08] px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-amber-300">
          coming soon
        </span>
      </div>
      <p className="mt-2 max-w-lg text-sm text-slate-400">{note}</p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState, useTransition } from "react";
import { submitBuild, approveBuild, rejectBuild } from "@/lib/actions-claude";

/**
 * "Build with AI" — the in-server AI assistant. Reuses the platform's guarded
 * Claude build pipeline (lib/actions-claude.ts): the customer describes an
 * outcome, Claude plans shell steps, the customer approves, and the worker
 * executes them over SSH on THIS server. Game-flavoured preset prompts seed the
 * box. Requires an effective Anthropic key on the account (submitBuild enforces
 * this and returns a clear message otherwise).
 */

type BuildState = { status: string; steps: number; log: string; plan?: string | null };
const TERMINAL = new Set(["DONE", "FAILED"]);

function presetsFor(label: string): string[] {
  const g = label || "game";
  return [
    `Configure my ${g} server for competitive PvP with balanced settings.`,
    `Install a balanced, popular mod pack for ${g} and enable it.`,
    `Optimize my ${g} server to run smoothly with up to 100 players.`,
    `Harden my ${g} server: sensible firewall, backups and anti-grief settings.`,
  ];
}

function parsePlan(raw?: string | null): { cmd: string; intent?: string }[] {
  if (!raw) return [];
  try {
    const p = JSON.parse(raw);
    if (Array.isArray(p)) return p.map((s) => (typeof s === "string" ? { cmd: s } : { cmd: String(s?.cmd ?? ""), intent: s?.intent })).filter((s) => s.cmd);
  } catch {
    /* ignore */
  }
  return [];
}

export function GameBuildAI({ serverId, gameFamily, gameLabel }: { serverId: string; gameFamily: string; gameLabel: string }) {
  const [prompt, setPrompt] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [buildId, setBuildId] = useState<string | null>(null);
  const [state, setState] = useState<BuildState | null>(null);
  const [pending, start] = useTransition();
  const logRef = useRef<HTMLPreElement>(null);
  void gameFamily;

  useEffect(() => {
    if (!buildId) return;
    let alive = true;
    let timer: ReturnType<typeof setTimeout>;
    const tick = async () => {
      try {
        const res = await fetch(`/api/claude/${buildId}`, { cache: "no-store" });
        if (res.ok) {
          const data = (await res.json()) as BuildState;
          if (alive) setState(data);
          if (data.status && TERMINAL.has(data.status)) return;
        }
      } catch {
        /* transient */
      }
      if (alive) timer = setTimeout(tick, 2000);
    };
    void tick();
    return () => {
      alive = false;
      clearTimeout(timer);
    };
  }, [buildId]);

  useEffect(() => {
    if (logRef.current) logRef.current.scrollTop = logRef.current.scrollHeight;
  }, [state?.log]);

  const status = state?.status ?? null;
  const inProgress = Boolean(buildId) && !(status && TERMINAL.has(status));
  const awaiting = status === "AWAITING_APPROVAL";
  const plan = parsePlan(state?.plan);

  function submit() {
    const clean = prompt.trim();
    if (clean.length < 8) {
      setError("Describe what you'd like to build (a sentence or two).");
      return;
    }
    setError(null);
    setState(null);
    start(async () => {
      const r = await submitBuild(serverId, clean);
      if (r.error) setError(r.error);
      else if (r.buildId) setBuildId(r.buildId);
    });
  }

  return (
    <div className="card relative overflow-hidden">
      <div
        aria-hidden
        className="pointer-events-none absolute -left-16 -top-16 h-48 w-48 rounded-full opacity-30 blur-3xl"
        style={{ background: "radial-gradient(circle, rgba(34,211,238,0.4), transparent 70%)" }}
      />
      <div className="relative flex items-center gap-2">
        <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-gradient-to-br from-accent-cyan/30 to-brand-500/30 text-base" aria-hidden>
          ✦
        </span>
        <div>
          <h2 className="text-lg font-semibold">Build with AI</h2>
          <p className="text-sm text-slate-400">Describe the outcome — Claude plans it, you approve, we run it on your {gameLabel} server.</p>
        </div>
      </div>

      <div className="relative mt-4 flex flex-wrap gap-2">
        {presetsFor(gameLabel).map((p) => (
          <button
            key={p}
            onClick={() => setPrompt(p)}
            disabled={inProgress}
            className="rounded-full border border-white/[0.08] bg-white/[0.03] px-3 py-1.5 text-xs text-slate-300 transition-colors hover:border-brand-400/40 hover:text-white disabled:opacity-40"
          >
            {p}
          </button>
        ))}
      </div>

      <textarea
        value={prompt}
        onChange={(e) => setPrompt(e.target.value)}
        rows={3}
        disabled={inProgress}
        placeholder="e.g. Configure my server for hardcore PvP and install an anti-cheat."
        className="input mt-3 w-full resize-y"
      />
      {error && <p className="mt-2 text-xs text-red-400">{error}</p>}

      <div className="mt-3 flex items-center gap-2">
        <button className="btn-primary disabled:opacity-40" disabled={inProgress || pending || prompt.trim().length < 8} onClick={submit}>
          {inProgress ? "Working…" : "Build it"}
        </button>
        {status && <span className="text-xs text-slate-500">Status: {status}</span>}
      </div>

      {plan.length > 0 && (
        <div className="mt-4 rounded-xl border border-white/[0.06] bg-navy-950/50 p-3">
          <p className="section-label">Planned steps</p>
          <ol className="mt-2 space-y-1 text-xs text-slate-300">
            {plan.map((s, i) => (
              <li key={i} className="font-mono">
                <span className="text-slate-500">{i + 1}.</span> {s.intent ? <span className="text-slate-400">{s.intent} — </span> : null}
                {s.cmd}
              </li>
            ))}
          </ol>
        </div>
      )}

      {awaiting && buildId && (
        <div className="mt-3 flex gap-2">
          <button className="btn-primary" onClick={() => start(async () => void (await approveBuild(buildId)))}>
            Approve &amp; run
          </button>
          <button className="btn-secondary" onClick={() => start(async () => void (await rejectBuild(buildId)))}>
            Reject
          </button>
        </div>
      )}

      {state?.log && (
        <pre ref={logRef} className="mt-4 max-h-56 overflow-auto rounded-xl border border-white/[0.06] bg-navy-950/80 p-3 font-mono text-[11px] leading-relaxed text-slate-300">
          {state.log}
        </pre>
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import { listGameSchedules, createGameSchedule, updateGameSchedule, deleteGameSchedule, type ScheduleRow } from "@/lib/actions-game-control";

/**
 * Scheduled automatic restarts (Settings tab). Thin client over the CRUD actions
 * in lib/actions-game-control.ts — the worker sweep fires each due schedule
 * (optionally warning players over RCON first). All times are UTC.
 */

function hhmm(h: number, m: number): string {
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

export function GameSchedules({ serverId }: { serverId: string }) {
  const [rows, setRows] = useState<ScheduleRow[]>([]);
  const [err, setErr] = useState<string | null>(null);
  const [hour, setHour] = useState(4);
  const [minute, setMinute] = useState(0);
  const [announce, setAnnounce] = useState(true);
  const [pending, start] = useTransition();

  const refresh = useCallback(() => {
    listGameSchedules(serverId).then((r) => {
      if (r.ok) setRows(r.schedules);
      else setErr(r.error);
    });
  }, [serverId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  function add() {
    start(async () => {
      setErr(null);
      const r = await createGameSchedule(serverId, hour, minute, announce);
      if (!r.ok) setErr(r.error);
      else refresh();
    });
  }
  function toggle(row: ScheduleRow) {
    start(async () => {
      const r = await updateGameSchedule(row.id, { enabled: !row.enabled });
      if (!r.ok) setErr(r.error);
      else refresh();
    });
  }
  function remove(id: string) {
    start(async () => {
      const r = await deleteGameSchedule(id);
      if (!r.ok) setErr(r.error);
      else refresh();
    });
  }

  return (
    <div className="card">
      <h3 className="font-semibold">Scheduled tasks — automatic restarts</h3>
      <p className="mt-1 text-sm text-slate-400">Restart the game server automatically at a set time each day (UTC). Players are warned over RCON first where supported.</p>
      {err && <p className="mt-3 text-sm text-amber-300">{err}</p>}

      <div className="mt-4 flex flex-wrap items-end gap-3">
        <label className="text-sm">
          <span className="mb-1 block font-medium">Time (UTC)</span>
          <span className="flex items-center gap-1">
            <select className="input w-20" value={hour} onChange={(e) => setHour(Number(e.target.value))}>
              {Array.from({ length: 24 }, (_, i) => (
                <option key={i} value={i}>
                  {String(i).padStart(2, "0")}
                </option>
              ))}
            </select>
            <span>:</span>
            <select className="input w-20" value={minute} onChange={(e) => setMinute(Number(e.target.value))}>
              {[0, 15, 30, 45].map((m) => (
                <option key={m} value={m}>
                  {String(m).padStart(2, "0")}
                </option>
              ))}
            </select>
          </span>
        </label>
        <label className="flex items-center gap-2 text-sm">
          <input type="checkbox" checked={announce} onChange={(e) => setAnnounce(e.target.checked)} />
          Warn players first
        </label>
        <button className="btn-primary" onClick={add} disabled={pending}>
          Add schedule
        </button>
      </div>

      {rows.length === 0 ? (
        <p className="mt-4 text-sm text-slate-400">No schedules yet.</p>
      ) : (
        <ul className="mt-4 divide-y divide-white/[0.06]">
          {rows.map((r) => (
            <li key={r.id} className="flex flex-wrap items-center justify-between gap-2 py-2.5 text-sm">
              <span className="flex items-center gap-3">
                <span className="font-mono">{hhmm(r.hour, r.minute)} UTC</span>
                <span className={`text-xs ${r.enabled ? "text-emerald-400" : "text-slate-500"}`}>{r.enabled ? "enabled" : "paused"}</span>
                {r.announce && <span className="text-xs text-slate-500">warns players</span>}
                {r.enabled && r.nextRunAt && <span className="text-xs text-slate-500">next: {new Date(r.nextRunAt).toLocaleString()}</span>}
              </span>
              <span className="flex gap-3">
                <button className="text-xs text-slate-400 hover:text-white" onClick={() => toggle(r)} disabled={pending}>
                  {r.enabled ? "Pause" : "Resume"}
                </button>
                <button className="text-xs text-red-400 hover:text-red-300" onClick={() => remove(r.id)} disabled={pending}>
                  Remove
                </button>
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

